use std::io

fn main() {
    let s = io::read_to_string(io::stdin()) ?? ""
    let toks: Vec<string> = s.split_whitespace().collect()
    let limit = 200000
    let mut comp: Vec<bool> = []
    let mut i = 0
    while i <= limit {
        comp.push(false)
        i += 1
    }
    let mut cnt: Vec<int> = []
    let mut last: Vec<int> = []
    let mut c = 0
    let mut l = -1
    i = 0
    while i <= limit {
        if i >= 2 && !comp[i] {
            c += 1
            l = i
            let mut j = i * i
            while j <= limit {
                comp[j] = true
                j += i
            }
        }
        cnt.push(c)
        last.push(l)
        i += 1
    }
    let t: int = toks[0].parse() ?? 0
    let mut k = 1
    while k <= t {
        let n: int = toks[k].parse() ?? 0
        if last[n] < 0 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
        k += 1
    }
}

